<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
$admin = requireAdmin();
$db = adminDb();
function h(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
try {
    $db->exec("CREATE TABLE IF NOT EXISTS smarttoolz_download_activity (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,guest_id CHAR(64) NULL,tool_slug VARCHAR(150) NOT NULL,page_url VARCHAR(500) NOT NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(500) NULL,downloaded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_user (user_id),INDEX idx_guest (guest_id),INDEX idx_tool (tool_slug),INDEX idx_date (downloaded_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
} catch(Throwable $e) {}
$rows=[];$total=0;$today=0;$guest=0;$logged=0;$tools=0;
try {
 $total=(int)$db->query('SELECT COUNT(*) FROM smarttoolz_download_activity')->fetchColumn();
 $today=(int)$db->query('SELECT COUNT(*) FROM smarttoolz_download_activity WHERE downloaded_at >= CURDATE()')->fetchColumn();
 $guest=(int)$db->query('SELECT COUNT(*) FROM smarttoolz_download_activity WHERE user_id IS NULL')->fetchColumn();
 $logged=(int)$db->query('SELECT COUNT(*) FROM smarttoolz_download_activity WHERE user_id IS NOT NULL')->fetchColumn();
 $tools=(int)$db->query('SELECT COUNT(DISTINCT tool_slug) FROM smarttoolz_download_activity')->fetchColumn();
 $rows=$db->query('SELECT id,user_id,guest_id,tool_slug,page_url,ip_address,user_agent,downloaded_at FROM smarttoolz_download_activity ORDER BY id DESC LIMIT 500')->fetchAll(PDO::FETCH_ASSOC);
} catch(Throwable $e) { $error=$e->getMessage(); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Download Tracking - SmartToolz Admin</title><style>body{margin:0;background:#f6f8fc;color:#172033;font-family:Inter,Arial,sans-serif}.wrap{max-width:1500px;margin:auto;padding:25px}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:20px}.top h1{margin:0;font-size:27px}.top p{margin:4px 0;color:#707b8e;font-size:13px}.links{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-block;padding:10px 13px;border-radius:10px;background:#635bff;color:#fff;text-decoration:none;font-size:12px;font-weight:800}.btn.gray{background:#eef0f5;color:#384257}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.card{background:#fff;border:1px solid #e4e8f0;border-radius:15px;padding:17px}.card b{display:block;font-size:23px}.card span{font-size:11px;color:#707b8e}.panel{margin-top:17px;background:#fff;border:1px solid #e4e8f0;border-radius:16px;padding:18px}.panel h2{font-size:17px;margin:0 0 14px}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:11px;min-width:1050px}th,td{padding:10px 8px;border-bottom:1px solid #edf0f4;text-align:left;vertical-align:top}th{background:#fafbfe;color:#596477}.tag{display:inline-block;padding:4px 7px;border-radius:999px;background:#eef0f5;font-weight:800}.tag.g{background:#fff4e5;color:#9a5a00}.tag.u{background:#eeedff;color:#635bff}.url{max-width:280px;word-break:break-all;color:#635bff}.ua{max-width:300px;word-break:break-word;color:#707b8e}.muted{color:#98a0ae}@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.wrap{padding:15px}.cards{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><h1>📥 Download Tracking</h1><p>Complete SmartToolz download activity for guests and logged-in users.</p></div><div class="links"><a class="btn gray" href="/smart-toolz/admin/">← Admin Panel</a><a class="btn" href="/smart-toolz/">SmartToolz</a></div></div><div class="cards"><div class="card"><b><?=number_format($total)?></b><span>Total Downloads</span></div><div class="card"><b><?=number_format($today)?></b><span>Today</span></div><div class="card"><b><?=number_format($guest)?></b><span>Guest Downloads</span></div><div class="card"><b><?=number_format($logged)?></b><span>Logged-in Downloads</span></div><div class="card"><b><?=number_format($tools)?></b><span>Tools Used</span></div></div><section class="panel"><h2>Download Activity — latest 500</h2><div class="table"><table><thead><tr><th>#</th><th>User / Guest ID</th><th>Tool</th><th>Page Link</th><th>IP</th><th>User Agent</th><th>Date / Time</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7" class="muted">No download activity recorded yet.</td></tr><?php else: foreach($rows as $r): ?><tr><td><?=h($r['id'])?></td><td><?php if(!empty($r['user_id'])): ?><span class="tag u">User #<?=h($r['user_id'])?></span><?php elseif(!empty($r['guest_id'])): ?><span class="tag g">Guest <?=h(substr($r['guest_id'],0,16))?>…</span><?php else: ?><span class="muted">Unknown</span><?php endif; ?></td><td><span class="tag"><?=h($r['tool_slug'])?></span></td><td class="url"><?=h($r['page_url'])?></td><td><?=h($r['ip_address'])?></td><td class="ua"><?=h($r['user_agent'])?></td><td><?=h($r['downloaded_at'])?></td></tr><?php endforeach; endif; ?></tbody></table></div></section></div></body></html>